export const SCHEDULE=Object.freeze({timeZone:'America/Chicago',seasonStart:{month:5,day:1},seasonEnd:{month:9,day:30},firstHour:10,lastHour:23,durationMinutes:5,closedDates:[],exceptions:{},lastChecked:'2026-11-15',source:'https://mwrd.org/what-we-do/reducing-flooding/chicago-area-waterway-system-caws/centennial-fountain'});
const cache=new Map();
function fmt(tz,opts){const key=JSON.stringify([tz,opts]);if(!cache.has(key))cache.set(key,new Intl.DateTimeFormat('en-US',{timeZone:tz,...opts}));return cache.get(key)}
function parts(date,tz){return Object.fromEntries(fmt(tz,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]))}
const key=d=>`${d.year}-${String(d.month).padStart(2,'0')}-${String(d.day).padStart(2,'0')}`;
function addDays(d,n){const v=new Date(Date.UTC(d.year,d.month-1,d.day+n));return {year:v.getUTCFullYear(),month:v.getUTCMonth()+1,day:v.getUTCDate()}}
function localHour(d,h,tz){const intended=Date.UTC(d.year,d.month-1,d.day,h);let instant=intended;for(let i=0;i<4;i++){const a=parts(new Date(instant),tz);const delta=intended-Date.UTC(a.year,a.month-1,a.day,a.hour,a.minute,a.second);if(!delta)return new Date(instant);instant+=delta}throw new RangeError('Configured local hour does not exist')}
function inSeason(d,c){const n=d.month*100+d.day;return n>=c.seasonStart.month*100+c.seasonStart.day&&n<=c.seasonEnd.month*100+c.seasonEnd.day}
const exception=(d,c)=>c.exceptions?.[key(d)]??{};
function closed(d,c){const e=exception(d,c);return c.closedDates?.includes(key(d))||e===false||e.closed===true||(Array.isArray(e.hours)&&!e.hours.length)}
function events(d,c){if(!inSeason(d,c)||closed(d,c))return [];const e=exception(d,c),duration=e.durationMinutes??c.durationMinutes,hours=e.hours??Array.from({length:c.lastHour-c.firstHour+1},(_,i)=>c.firstHour+i);if(!Number.isFinite(duration)||duration<=0||duration>60||!Array.isArray(hours)||hours.some(h=>!Number.isInteger(h)||h<0||h>23))throw new RangeError('Invalid schedule');return [...new Set(hours)].sort((a,b)=>a-b).map(h=>{const start=localHour(d,h,c.timeZone);return {start,end:new Date(+start+duration*60000)}})}
export function getSchedule(now=new Date(),config=SCHEDULE){const current=new Date(now),c={...SCHEDULE,...config};if(!Number.isFinite(+current)||!Number.isInteger(c.firstHour)||!Number.isInteger(c.lastHour)||c.firstHour<0||c.lastHour>23||c.firstHour>c.lastHour)throw new RangeError('Invalid date or schedule');const today=parts(current,c.timeZone),todayEvents=events(today,c),active=todayEvents.find(e=>current>=e.start&&current<e.end);let next=null;for(let offset=0;offset<=732&&!next;offset++)next=(offset===0?todayEvents:events(addDays(today,offset),c)).find(e=>e.start>current)?.start??null;
const state=active?'spraying':!inSeason(today,c)?'off-season':closed(today,c)?'closed':'upcoming';const targetAt=active?.end??next;let dateLabel='',timeLabel='';if(next){const nd=parts(next,c.timeZone);dateLabel=key(nd)===key(today)?'Today':key(nd)===key(addDays(today,1))?'Tomorrow':fmt(c.timeZone,{month:'long',day:'numeric',...(nd.year!==today.year?{year:'numeric'}:{})}).format(next);timeLabel=fmt(c.timeZone,{hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(next)}return {state,next,targetAt,secondsRemaining:targetAt?Math.max(0,Math.ceil((targetAt-current)/1000)):null,startsAt:active?.start??null,endsAt:active?.end??null,localDate:key(today),dateLabel,timeLabel,nextLabel:next?`${dateLabel} at ${timeLabel}`:'No scheduled date available',reason:state==='closed'?(exception(today,c).reason||'A date-specific closure is listed.'):null,lastChecked:c.lastChecked,source:c.source,timeZone:c.timeZone}}
